import fs from 'node:fs/promises';

const DATA_DIR = path.resolve('data');

export async function listTools() {
  return [
    {
      name: 'file_metadata',
      description: 'Return metadata (relative path, byte size, lowercase extension) for a file under the workspace data directory. Does not expose file contents.',
      inputSchema: {
        type: 'object',
        properties: {
          path: {
            type: 'string',
            description: 'Relative path of the file within the data directory.'
          }
        },
        required: ['path'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'file_metadata') {
    throw new Error('Unknown tool: ' + name);
  }
  const raw = args && typeof args.path === 'string' ? args.path : '';
  if (!raw) {
    throw new Error('path is required');
  }

  // Reject traversal and absolute paths; resolve strictly inside data dir.
  const resolved = path.resolve(DATA_DIR, raw);
  const rel = path.relative(DATA_DIR, resolved);
  if (rel === '' || rel === '.' || rel.startsWith('..') || path.isAbsolute(rel)) {
    throw new Error('Invalid path: must stay within the data directory');
  }

  let stat;
  try {
    stat = await fs.stat(resolved);
  } catch (e) {
    throw new Error('File not found: ' + raw);
  }
  if (!stat.isFile()) {
    throw new Error('Not a file: ' + raw);
  }

  const ext = path.extname(resolved).toLowerCase();
  const text = `path: ${rel}\nsize: ${stat.size}\next: ${ext}`;

  return {
    content: [{ type: 'text', text }]
  };
}
