  const resolved = path.resolve(DATA_DIR, raw);
  const rel = path.relative(DATA_DIR, resolved);
  if (rel === '' || rel === '.' || rel.startsWith('..') || path.isAbsolute(rel)) {
    throw new Error('Invalid path: must stay within the data directory');
  }

  let stat;
  try {
    stat = await fs.stat(resolved);
  } catch (e) {
