  // missing
  console.log('--- missing ---');
  try { await callTool('file_metadata', {path:'nope.txt'}); console.log('NO ERROR'); }
  catch(e){ console.log('ERROR:', e.message); }

  // unknown tool
  console.log('--- unknown tool ---');
  try { await callTool('foobar', {}); console.log('NO ERROR'); }
  catch(e){ console.log('ERROR:', e.message); }

  // extra props (simulated - schema handles strictness, but callTool ignores unknown)
  console.log('--- nested traversal ---');
  try { await callTool('file_metadata', {path:'a/../../etc/hosts'}); console.log('NO ERROR'); }
  catch(e){ console.log('ERROR:', e.message); }
});
